/usr/bin/bash -lc "python - <<'PY'
import reproduce
p = reproduce.import_pybamm()
sc = reproduce.SCENARIOS[1]
m = p.lithium_ion.DFN(sc['options'])
sim = p.Simulation(m, parameter_values=reproduce.build_parameter_values(p, 'Xu2019'), C_rate=0.65)
sim.build()
for key, bc in sim._model.boundary_conditions.items():
    print('BC', type(key).__name__, key.domain, str(key)[:130], {s:(str(v[0])[:70],v[1]) for s,v in bc.items()})
for name in ['Positive electrode potential [V]', 'Separator electrolyte potential [V]', 'Positive electrolyte potential [V]', 'Electrolyte potential [V]']:
    sym = sim._model.variables[name]
    print('GRAD', name, sim._disc.process_symbol(p.grad(sym)).shape, 'BC', sym in sim._disc.bcs)
original = p.FiniteVolume.process_binary_operators
def process(self, bin_op, left, right, disc_left, disc_right):
    try:
        return original(self, bin_op, left, right, disc_left, disc_right)
    except p.ShapeError:
        print('FAILED BINARY', type(bin_op).__name__, bin_op.domain, str(bin_op)[:400], flush=True)
        print('SHAPES', disc_left.shape, disc_right.shape, flush=True)
        raise
p.FiniteVolume.process_binary_operators = process
try:
    reproduce.run_scenario(p, reproduce.SCENARIOS[2])
except p.ShapeError:
    pass
PY"

